-- Migration 245 additive-compatible livecheck; the runtime must require result=1.
WITH
successor_table AS (
  SELECT table_name FROM JSON_TABLE('["dp_pull_snapshot_fingerprint_count","dp_pull_snapshot_verify_page","dp_pull_snapshot_apply_progress","dp_pull_snapshot_effective_item","dp_pull_snapshot_current_head"]','$[*]' COLUMNS(table_name VARCHAR(64) PATH '$')) j
),
column_contract AS (
  SELECT j.table_name,j.column_names,j.expected_count,j.expected_sha256 FROM JSON_TABLE('[{"t":"dp_pull_snapshot_fingerprint_count","n":"task_id,content_fingerprint,pass_one_count,pass_two_count,gmt_create,gmt_updated","c":6,"h":"d49cc6cf6d72d64da352069ef29ee3a4805a3be809ebfa167c3a11e949dbac7c"},{"t":"dp_pull_snapshot_verify_page","n":"task_id,page_no,next_page,is_last_page,total_pages,source_item_count,business_skipped_item_count,page_digest_sha256,gmt_create","c":9,"h":"f5f79b70659c3fc5d7003979a579db25c556e38c1b7df80d2e2b6ede3c164dd9"},{"t":"dp_pull_snapshot_apply_progress","n":"task_id,active_fence_epoch,cursor_page_no,cursor_item_ordinal,prepared_item_count,absence_unsafe_item_count,effective_item_count,target_ref_type,target_ref_id,carry_mode,carry_source_task_id,carry_source_head_version,carry_cursor_identity,state,gmt_create,gmt_updated","c":16,"h":"859650de8ffbbf79c9e7c7dcbfb7efc6cc40a8abf38dc843c22bb9bde4f9d281"},{"t":"dp_pull_snapshot_effective_item","n":"task_id,stable_identity,source_page_no,source_item_ordinal,content_fingerprint,payload,gmt_create","c":7,"h":"e30eca82f1e728373895d7dd096aaf400872e1473bac0b1c2243ccf757cefc31"},{"t":"dp_pull_snapshot_current_head","n":"operation_code,scope_key,task_id,business_window_key,schedule_slot,retire_missing,version_no,sealed_at,gmt_create,gmt_updated","c":10,"h":"e9e19e3026cec0a8bc7b2f14db1e454af6aecceeaed717886e636925104f9284"},{"t":"dp_pull_snapshot_stage","n":"collection_mode,verification_state,pass_one_page_count,pass_one_source_item_count,verification_next_page,verification_page_count,verification_source_item_count,comparison_after_fingerprint,comparison_digest_sha256,comparison_key_count,comparison_source_item_count","c":11,"h":"5c6aae8bc1d0b1ea0e84d15ea7602530a722cd36f8847327ea37ffcde4533d16"},{"t":"dp_pull_snapshot_stage_item","n":"validated_identity_candidate,absence_reconciliation_safe","c":2,"h":"cc5a54083c1ec9e4ecbbe6f1c6f757a204334ca4de0170b09f2a5ec5f9953d67"},{"t":"dp_pull_snapshot_apply","n":"effective_item_count,carry_mode,carried_from_task_id","c":3,"h":"e9a0e70b0e7906fe24fe9edc87749fa761616ff3fa83576038b8380212947588"},{"t":"official_warehouse_inventory_snapshot_line","n":"snapshot_stable_identity","c":1,"h":"14f7bd73e6a4771507040590e7c6d8bc0176b4b0cbbc29b54bc0a3688e064b06"},{"t":"official_warehouse_inventory_sync_batch","n":"total_pages,total_rows,valid_rows,error_rows","c":4,"h":"b5e96f664c1b6e06d9010469ddbe6c84fe907d59121949cd4f441a8965c38a61"}]','$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t',column_names VARCHAR(4000) PATH '$.n',expected_count INT PATH '$.c',expected_sha256 CHAR(64) PATH '$.h')) j
),
actual_column_contract AS (
  SELECT e.table_name,COUNT(*) actual_count,SHA2(GROUP_CONCAT(CONCAT_WS('|',c.column_name,LOWER(c.column_type),c.is_nullable,COALESCE(LOWER(c.character_set_name),''),COALESCE(LOWER(c.collation_name),''),
    CASE WHEN c.column_default IS NULL THEN '-' WHEN c.data_type='bit' AND LOWER(c.column_default) IN ('0','b''0''') THEN '0' ELSE LOWER(c.column_default) END,
    REPLACE(REPLACE(LOWER(c.extra),'default_generated',''),' ','')) ORDER BY c.ordinal_position SEPARATOR ';'),256) actual_sha256
  FROM column_contract e LEFT JOIN information_schema.columns c ON c.table_schema=DATABASE() AND c.table_name=e.table_name AND FIND_IN_SET(c.column_name,e.column_names)>0 GROUP BY e.table_name
),
required_index AS (
  SELECT j.table_name,j.index_name,j.non_unique,j.index_columns FROM JSON_TABLE('[{"t":"dp_pull_snapshot_fingerprint_count","n":"PRIMARY","u":0,"c":"task_id,content_fingerprint"},{"t":"dp_pull_snapshot_verify_page","n":"PRIMARY","u":0,"c":"task_id,page_no"},{"t":"dp_pull_snapshot_apply_progress","n":"PRIMARY","u":0,"c":"task_id"},{"t":"dp_pull_snapshot_apply_progress","n":"idx_dp_snapshot_progress_target","u":1,"c":"target_ref_type,target_ref_id,state,task_id"},{"t":"dp_pull_snapshot_apply_progress","n":"idx_dp_snapshot_progress_carry_source","u":1,"c":"carry_source_task_id,task_id,state"},{"t":"dp_pull_snapshot_effective_item","n":"PRIMARY","u":0,"c":"task_id,stable_identity"},{"t":"dp_pull_snapshot_current_head","n":"PRIMARY","u":0,"c":"operation_code,scope_key"},{"t":"dp_pull_snapshot_current_head","n":"uk_dp_snapshot_current_head_task","u":0,"c":"task_id"},{"t":"dp_pull_snapshot_stage_item","n":"idx_dp_snapshot_item_canonical","u":1,"c":"task_id,stable_identity,validated_identity_candidate,page_no,item_ordinal"},{"t":"dp_pull_snapshot_apply","n":"idx_dp_snapshot_apply_carry_source","u":1,"c":"carried_from_task_id,task_id"},{"t":"official_warehouse_inventory_snapshot_line","n":"uk_official_inventory_batch_stable_identity","u":0,"c":"sync_batch_id,snapshot_stable_identity"},{"t":"official_warehouse_inventory_snapshot_line","n":"idx_official_inventory_carry","u":1,"c":"sync_batch_id,snapshot_stable_identity,is_deleted,id"},{"t":"dp_pull_task","n":"idx_dp_pull_task_business_scope","u":1,"c":"operation_code,owner_user_id,logical_store_id,project_code,store_code,site_code,id,scope_key"}]','$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t',index_name VARCHAR(64) PATH '$.n',non_unique INT PATH '$.u',index_columns VARCHAR(1000) PATH '$.c')) j
),
actual_index AS (
  SELECT s.table_name,s.index_name,MIN(s.non_unique) non_unique,GROUP_CONCAT(s.column_name ORDER BY s.seq_in_index SEPARATOR ',') index_columns,
    MIN(s.index_type='BTREE' AND s.is_visible='YES' AND s.sub_part IS NULL AND s.expression IS NULL AND s.collation='A') safe_shape
  FROM information_schema.statistics s JOIN (SELECT DISTINCT table_name FROM required_index UNION SELECT table_name FROM successor_table) e ON e.table_name=s.table_name
  WHERE s.table_schema=DATABASE() GROUP BY s.table_name,s.index_name
),
required_check AS (
  SELECT j.table_name,j.constraint_name,j.required_pattern FROM JSON_TABLE('[{"t":"dp_pull_snapshot_fingerprint_count","n":"chk_dp_snapshot_fingerprint_digest","p":"regexp_like.*content_fingerprint.*64"},{"t":"dp_pull_snapshot_fingerprint_count","n":"chk_dp_snapshot_fingerprint_counts","p":"pass_one_count>=0.*pass_two_count>=0.*pass_one_count>0.*pass_two_count>0"},{"t":"dp_pull_snapshot_verify_page","n":"chk_dp_snapshot_verify_page_shape","p":"page_no>0.*next_page.*page_no.*1.*source_item_count>=0.*business_skipped_item_countbetween0andsource_item_count"},{"t":"dp_pull_snapshot_verify_page","n":"chk_dp_snapshot_verify_page_digest","p":"regexp_like.*page_digest_sha256.*64"},{"t":"dp_pull_snapshot_apply_progress","n":"chk_dp_snapshot_progress_fence","p":"active_fence_epoch>0"},{"t":"dp_pull_snapshot_apply_progress","n":"chk_dp_snapshot_progress_cursor","p":"cursor_page_no=0.*cursor_item_ordinal=-1.*cursor_page_no>0.*cursor_item_ordinal>=0"},{"t":"dp_pull_snapshot_apply_progress","n":"chk_dp_snapshot_progress_count","p":"prepared_item_count>=0.*absence_unsafe_item_countbetween0andprepared_item_count.*effective_item_count>=0"},{"t":"dp_pull_snapshot_apply_progress","n":"chk_dp_snapshot_progress_target","p":"target_ref_typeisnull.*target_ref_idisnull.*target_ref_typeisnotnull.*target_ref_idisnotnull.*target_ref_id>0"},{"t":"dp_pull_snapshot_apply_progress","n":"chk_dp_snapshot_progress_carry","p":"state=''preparing''.*state=''carrying''.*carry_source_head_versionisnotnull.*state=''sealed''.*carry_mode=''none''.*carry_modein"},{"t":"dp_pull_snapshot_apply_progress","n":"chk_dp_snapshot_progress_state","p":"statein.*preparing.*carrying.*sealed"},{"t":"dp_pull_snapshot_effective_item","n":"chk_dp_snapshot_effective_identity","p":"stable_identity.*source_page_no>0.*source_item_ordinal>=0"},{"t":"dp_pull_snapshot_effective_item","n":"chk_dp_snapshot_effective_fingerprint","p":"regexp_like.*content_fingerprint.*64"},{"t":"dp_pull_snapshot_effective_item","n":"chk_dp_snapshot_effective_payload","p":"length.*payload.*<=16711680"},{"t":"dp_pull_snapshot_current_head","n":"chk_dp_snapshot_head_operation","p":"operation_codein.*dp04.*dp07a"},{"t":"dp_pull_snapshot_current_head","n":"chk_dp_snapshot_head_identity","p":"scope_key.*business_window_key.*version_no>=0"},{"t":"dp_pull_snapshot_stage","n":"chk_dp_snapshot_stage_authority_v2","p":"provider_authority.*complete_response.*two_pass_required.*two_pass_observation"},{"t":"dp_pull_snapshot_stage","n":"chk_dp_snapshot_stage_two_pass","p":"pass_one_page_count>=0.*verification_next_page.*comparison_digest_sha256"},{"t":"dp_pull_snapshot_apply","n":"chk_dp_snapshot_apply_authority_v2","p":"complete_response.*two_pass_observation.*declared_collection_count>=0"},{"t":"dp_pull_snapshot_apply","n":"chk_dp_snapshot_apply_effective","p":"effective_item_count>=applied_item_count.*carry_mode=''none''.*carried_from_task_idisnull.*carried_from_task_idisnotnull"}]','$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t',constraint_name VARCHAR(64) PATH '$.n',required_pattern VARCHAR(1000) PATH '$.p')) j
),
actual_check AS (
  SELECT tc.table_name,tc.constraint_name,tc.enforced,
    REPLACE(REPLACE(REPLACE(REGEXP_REPLACE(LOWER(cc.check_clause),'[`()[:space:]]+',''),CONCAT(CHAR(92),CHAR(39)),CHAR(39)),'_utf8mb4',''),'_ascii','') check_clause
  FROM information_schema.table_constraints tc JOIN information_schema.check_constraints cc ON cc.constraint_schema=tc.constraint_schema AND cc.constraint_name=tc.constraint_name
  JOIN (SELECT DISTINCT table_name FROM required_check UNION SELECT table_name FROM successor_table) e ON e.table_name=tc.table_name WHERE tc.constraint_schema=DATABASE() AND tc.constraint_type='CHECK'
),
required_fk AS (
  SELECT j.table_name,j.constraint_name,j.child_columns,j.referenced_table_name,j.referenced_columns FROM JSON_TABLE('[{"t":"dp_pull_snapshot_fingerprint_count","n":"fk_dp_snapshot_fingerprint_stage","c":"task_id","r":"dp_pull_snapshot_stage","rc":"task_id"},{"t":"dp_pull_snapshot_verify_page","n":"fk_dp_snapshot_verify_stage","c":"task_id","r":"dp_pull_snapshot_stage","rc":"task_id"},{"t":"dp_pull_snapshot_apply_progress","n":"fk_dp_snapshot_progress_task","c":"task_id","r":"dp_pull_task","rc":"id"},{"t":"dp_pull_snapshot_apply_progress","n":"fk_dp_snapshot_progress_carry_source","c":"carry_source_task_id","r":"dp_pull_task","rc":"id"},{"t":"dp_pull_snapshot_effective_item","n":"fk_dp_snapshot_effective_task","c":"task_id","r":"dp_pull_task","rc":"id"},{"t":"dp_pull_snapshot_current_head","n":"fk_dp_snapshot_head_task","c":"task_id","r":"dp_pull_task","rc":"id"},{"t":"dp_pull_snapshot_apply","n":"fk_dp_snapshot_apply_carry_source","c":"carried_from_task_id","r":"dp_pull_task","rc":"id"}]','$[*]' COLUMNS(table_name VARCHAR(64) PATH '$.t',constraint_name VARCHAR(64) PATH '$.n',child_columns VARCHAR(1000) PATH '$.c',referenced_table_name VARCHAR(64) PATH '$.r',referenced_columns VARCHAR(1000) PATH '$.rc')) j
),
actual_fk AS (
  SELECT k.table_name,k.constraint_name,GROUP_CONCAT(k.column_name ORDER BY k.ordinal_position SEPARATOR ',') child_columns,MAX(k.referenced_table_name) referenced_table_name,
    GROUP_CONCAT(k.referenced_column_name ORDER BY k.ordinal_position SEPARATOR ',') referenced_columns,MAX(r.delete_rule) delete_rule,MAX(r.update_rule) update_rule
  FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema=k.constraint_schema AND r.constraint_name=k.constraint_name
  JOIN (SELECT DISTINCT table_name FROM required_fk UNION SELECT table_name FROM successor_table) e ON e.table_name=k.table_name WHERE k.constraint_schema=DATABASE() AND k.referenced_table_name IS NOT NULL GROUP BY k.table_name,k.constraint_name
),
expected_view AS (
  SELECT j.view_name,j.view_columns FROM JSON_TABLE('[{"n":"official_warehouse_current_inventory_snapshot_line_raw","c":"id,sync_batch_id,snapshot_stable_identity,owner_user_id,logical_store_id,store_code,site_code,project_code,partner_id,product_master_id,product_variant_id,product_site_offer_id,partner_sku,psku_code,noon_sku,pbarcode,barcode,warehouse_code,country_code,inventory_type,reason_code,classification_code,stock_bucket,qty,inventory_snapshot_at,title_cache,brand_cache,match_status,match_message,raw_payload_json,is_current,is_deleted,created_by,updated_by,gmt_create,gmt_updated"},{"n":"official_warehouse_effective_inventory_snapshot_line","c":"id,sync_batch_id,snapshot_stable_identity,owner_user_id,logical_store_id,store_code,site_code,project_code,partner_id,product_master_id,product_variant_id,product_site_offer_id,partner_sku,psku_code,noon_sku,pbarcode,barcode,warehouse_code,country_code,inventory_type,reason_code,classification_code,stock_bucket,qty,inventory_snapshot_at,title_cache,brand_cache,match_status,match_message,raw_payload_json,is_current,is_deleted,created_by,updated_by,gmt_create,gmt_updated"}]','$[*]' COLUMNS(view_name VARCHAR(64) PATH '$.n',view_columns VARCHAR(4000) PATH '$.c')) j
),
actual_view AS (
  SELECT v.table_name view_name,v.security_type,v.check_option,v.is_updatable,LOWER(REGEXP_REPLACE(v.view_definition,'[`[:space:]]+','')) definition,GROUP_CONCAT(c.column_name ORDER BY c.ordinal_position SEPARATOR ',') view_columns
  FROM information_schema.views v JOIN information_schema.columns c ON c.table_schema=v.table_schema AND c.table_name=v.table_name JOIN expected_view e ON e.view_name=v.table_name
  WHERE v.table_schema=DATABASE() GROUP BY v.table_name,v.security_type,v.check_option,v.is_updatable,v.view_definition
),
protected_stage AS (
  SELECT s.task_id,s.active_fence_epoch,s.declared_total_pages,s.known_last_page,s.poison_code,s.authority_kind,s.authority_token_sha256,s.snapshot_as_of_utc,s.declared_collection_count,s.version_no,s.gmt_create,s.gmt_updated,s.collection_mode,s.verification_state,s.pass_one_page_count,s.pass_one_source_item_count,s.verification_next_page,s.verification_page_count,s.verification_source_item_count,s.comparison_after_fingerprint,s.comparison_digest_sha256,s.comparison_key_count,s.comparison_source_item_count FROM dp_pull_snapshot_stage s JOIN dp_pull_task t ON t.id=s.task_id
  WHERE t.state NOT IN ('SUCCEEDED','FAILED','SUPERSEDED') OR EXISTS (SELECT 1 FROM dp_pull_snapshot_current_head h WHERE h.task_id=s.task_id)
    OR EXISTS (SELECT 1 FROM dp_pull_snapshot_apply_progress p JOIN dp_pull_task consumer ON consumer.id=p.task_id WHERE p.carry_source_task_id=s.task_id AND consumer.state NOT IN ('SUCCEEDED','FAILED','SUPERSEDED'))
),
stage_page_shape AS (
  SELECT p.task_id,p.page_no,p.next_page,p.is_last_page,p.total_pages,p.item_count,p.source_item_count,p.business_skipped_item_count,
    COUNT(i.item_ordinal) actual_count,MIN(i.item_ordinal) first_ordinal,MAX(i.item_ordinal) last_ordinal
  FROM dp_pull_snapshot_stage_page p JOIN protected_stage s ON s.task_id=p.task_id AND s.poison_code IS NULL LEFT JOIN dp_pull_snapshot_stage_item i ON i.task_id=p.task_id AND i.page_no=p.page_no
  GROUP BY p.task_id,p.page_no,p.next_page,p.is_last_page,p.total_pages,p.item_count,p.source_item_count,p.business_skipped_item_count
),
pass_one_fingerprint_actual AS (
  SELECT i.task_id,i.content_fingerprint,COUNT(*) pass_one_count FROM dp_pull_snapshot_stage_item i JOIN protected_stage s ON s.task_id=i.task_id AND s.poison_code IS NULL AND s.collection_mode='TWO_PASS_REQUIRED' GROUP BY i.task_id,i.content_fingerprint
),
verify_page_shape AS (
  SELECT v.task_id,v.page_no,v.next_page,v.is_last_page,v.total_pages,v.source_item_count,v.business_skipped_item_count,v.page_digest_sha256,v.gmt_create,p.page_no stage_page_no,p.next_page stage_next_page,p.is_last_page stage_last_page,p.total_pages stage_total_pages,p.source_item_count stage_source_count,p.business_skipped_item_count stage_skip_count
  FROM dp_pull_snapshot_verify_page v JOIN protected_stage s ON s.task_id=v.task_id AND s.poison_code IS NULL AND s.collection_mode='TWO_PASS_REQUIRED' LEFT JOIN dp_pull_snapshot_stage_page p ON p.task_id=v.task_id AND p.page_no=v.page_no
),
protected_progress AS (
  SELECT p.task_id,p.active_fence_epoch,p.cursor_page_no,p.cursor_item_ordinal,p.prepared_item_count,p.absence_unsafe_item_count,p.effective_item_count,p.target_ref_type,p.target_ref_id,p.carry_mode,p.carry_source_task_id,p.carry_source_head_version,p.carry_cursor_identity,p.state,t.operation_code,t.scope_key,t.business_window_key,t.schedule_slot,t.fence_epoch,t.state task_state
  FROM dp_pull_snapshot_apply_progress p JOIN dp_pull_task t ON t.id=p.task_id
  WHERE t.state NOT IN ('SUCCEEDED','FAILED','SUPERSEDED') OR EXISTS (SELECT 1 FROM dp_pull_snapshot_current_head h WHERE h.task_id=p.task_id)
    OR EXISTS (SELECT 1 FROM dp_pull_snapshot_apply_progress consumer JOIN dp_pull_task ct ON ct.id=consumer.task_id WHERE consumer.carry_source_task_id=p.task_id AND ct.state NOT IN ('SUCCEEDED','FAILED','SUPERSEDED'))
),
valid_runtime_batch AS (
  SELECT h.task_id,p.target_ref_id batch_id FROM dp_pull_snapshot_current_head h JOIN dp_pull_task t ON t.id=h.task_id
  JOIN dp_pull_snapshot_apply_progress p ON p.task_id=h.task_id AND p.state='SEALED' AND p.target_ref_type='OFFICIAL_WAREHOUSE_INVENTORY_BATCH'
  JOIN dp_pull_snapshot_apply a ON a.task_id=h.task_id JOIN official_warehouse_inventory_sync_batch b ON b.id=p.target_ref_id
  WHERE h.operation_code='DP07A' AND h.scope_key=t.scope_key AND h.business_window_key=t.business_window_key AND h.schedule_slot=t.schedule_slot
    AND a.operation_code=h.operation_code AND a.scope_key=h.scope_key AND a.business_window_key=h.business_window_key AND a.applied_fence_epoch=p.active_fence_epoch
    AND a.effective_item_count=p.effective_item_count AND a.carry_mode=p.carry_mode AND a.carried_from_task_id <=> p.carry_source_task_id
    AND b.status='IMPORTED' AND b.source_type='FBN_INVENTORY_API' AND b.is_deleted=b'0' AND b.owner_user_id=t.owner_user_id AND b.logical_store_id <=> t.logical_store_id
    AND BINARY b.project_code <=> BINARY t.project_code AND BINARY b.store_code=BINARY t.store_code AND BINARY UPPER(b.site_code)=BINARY UPPER(t.site_code)
    AND b.total_pages=a.last_page AND b.total_rows=a.effective_item_count AND b.valid_rows=b.total_rows AND b.error_rows=a.business_skipped_item_count
    AND a.effective_item_count=(SELECT COUNT(*) FROM official_warehouse_inventory_snapshot_line l WHERE l.sync_batch_id=b.id AND l.is_deleted=b'0' AND l.is_current=b'0' AND l.snapshot_stable_identity IS NOT NULL AND l.owner_user_id=t.owner_user_id AND l.logical_store_id <=> t.logical_store_id AND BINARY l.project_code <=> BINARY t.project_code AND BINARY l.store_code=BINARY t.store_code AND BINARY UPPER(l.site_code)=BINARY UPPER(t.site_code))
    AND NOT EXISTS (SELECT 1 FROM official_warehouse_inventory_snapshot_line l WHERE l.sync_batch_id=b.id AND l.is_deleted=b'0' AND (l.is_current<>b'0' OR l.snapshot_stable_identity IS NULL OR l.owner_user_id<>t.owner_user_id OR NOT (l.logical_store_id <=> t.logical_store_id) OR NOT (BINARY l.project_code <=> BINARY t.project_code) OR BINARY l.store_code<>BINARY t.store_code OR BINARY UPPER(l.site_code)<>BINARY UPPER(t.site_code)))
)
SELECT IF(
  (SELECT COUNT(*) FROM information_schema.tables t JOIN successor_table e ON e.table_name=t.table_name WHERE t.table_schema=DATABASE() AND t.table_type='BASE TABLE' AND UPPER(t.engine)='INNODB' AND LOWER(t.table_collation)='utf8mb4_bin')=5
  AND NOT EXISTS (SELECT 1 FROM column_contract e LEFT JOIN actual_column_contract a ON a.table_name=e.table_name WHERE a.table_name IS NULL OR a.actual_count<>e.expected_count OR a.actual_sha256<>e.expected_sha256)
  AND NOT EXISTS (SELECT 1 FROM successor_table t JOIN column_contract e ON e.table_name=t.table_name JOIN information_schema.columns c ON c.table_schema=DATABASE() AND c.table_name=t.table_name WHERE FIND_IN_SET(c.column_name,e.column_names)=0 AND (c.extra LIKE '%auto_increment%' OR (c.is_nullable='NO' AND c.column_default IS NULL AND c.generation_expression='')))
  AND NOT EXISTS (SELECT 1 FROM required_index e LEFT JOIN actual_index a ON a.table_name=e.table_name AND a.index_name=e.index_name WHERE a.table_name IS NULL OR a.non_unique<>e.non_unique OR a.index_columns<>e.index_columns OR a.safe_shape<>1)
  AND NOT EXISTS (SELECT 1 FROM successor_table t JOIN actual_index a ON a.table_name=t.table_name LEFT JOIN required_index e ON e.table_name=a.table_name AND e.index_name=a.index_name WHERE e.table_name IS NULL AND (a.non_unique<>1 OR a.safe_shape<>1))
  AND NOT EXISTS (SELECT 1 FROM required_check e LEFT JOIN actual_check a ON a.table_name=e.table_name AND a.constraint_name=e.constraint_name WHERE a.table_name IS NULL OR a.enforced<>'YES' OR a.check_clause NOT REGEXP e.required_pattern)
  AND NOT EXISTS (SELECT 1 FROM successor_table t JOIN actual_check a ON a.table_name=t.table_name LEFT JOIN required_check e ON e.table_name=a.table_name AND e.constraint_name=a.constraint_name WHERE e.table_name IS NULL)
  AND NOT EXISTS (SELECT 1 FROM required_fk e LEFT JOIN actual_fk a ON a.table_name=e.table_name AND a.constraint_name=e.constraint_name WHERE a.table_name IS NULL OR a.child_columns<>e.child_columns OR a.referenced_table_name<>e.referenced_table_name OR a.referenced_columns<>e.referenced_columns OR a.delete_rule<>'RESTRICT' OR a.update_rule<>'RESTRICT')
